def backfill_work_assignments_and_navigation(apps, schema_editor):
    OrderItem = apps.get_model('store', 'OrderItem')
    NavigationItem = apps.get_model('store', 'NavigationItem')
    AccessRole = apps.get_model('store', 'AccessRole')
    database = schema_editor.connection.alias
    for item in OrderItem.objects.using(database).select_related('order', 'product').iterator():
        craftswoman_id = item.product.craftswoman_id or item.order.craftswoman_id
        item.craftswoman_id = craftswoman_id
        item.status = item.order.status
        # Existing orders do not store the original assignment timestamp.
        item.assigned_at = None
        item.save(update_fields=('craftswoman', 'status', 'assigned_at'))

    if not NavigationItem.objects.using(database).filter(route_name='admin.access').exists():
        root_role = AccessRole.objects.using(database).get(code='superadmin')
        item = NavigationItem.objects.using(database).create(
            label='Roles y permisos',
            route_name='admin.access',
            description='Administra roles, permisos y vistas del sistema.',
            order=90,
            active=True,
        )
        item.roles.add(root_role)


